"""Reusable patient/result dashboard; every displayed finding comes from saved data."""
from pathlib import Path
import json,html,re,gzip,base64
VERSION='patient-dashboard/1'

def summary_metrics(answer, rows):
 """Describe the saved result shape without substituting row count for its value."""
 result=[]
 for key,label in (('count','Count returned'),('value','Computed value')):
  if key in answer:
   result.append({'value':answer[key],'label':answer.get('unit')or label})
   break
 if rows:
  ids={str(r['patient_id'])for r in rows if r.get('patient_id')is not None}
  if ids:result.append({'value':len(ids),'label':'Patients in returned records'})
  result.append({'value':len(rows),'label':'Complete result rows'})
 return result

def payload(context,*,title='Evidence into next steps',labels=None,evidence=None,layout='explore'):
 if layout not in ('command','brief','explore'):raise ValueError('Unknown report layout')
 from .patient_evidence import RECOMMENDATION_FIELD_PATTERN,projection,review_cards,source_reading_notice
 a=context['answer'];parts=[]
 def visit(part):
  parts.append(part)
  for s in part.get('sections')or[]:
   if isinstance(s,dict)and isinstance(s.get('answer'),dict):visit(s['answer'])
 visit(a);rows=[r for part in parts for r in part.get('table')or[]if isinstance(r,dict)]
 evidence=evidence if evidence is not None else projection(context)
 cards=review_cards(context,evidence)
 worklist=[]
 for row in rows:
  c=cards.get(row.get('patient_id'))
  if not c:
   worklist.append({**row,'captured_answer_status':a.get('status'),
    'answer_source_reading_status':(context.get('source_disposition')or{}).get('status','not_assessed'),
    'source_interpretation_notice':source_reading_notice(context)})
   continue
  p=c['profile'];care={t['role']:t for t in c['care_team']}
  def team(role):return '; '.join(a['name'] for a in care[role]['current'])or care[role]['status']
  worklist.append({'patient_name':c['patient_name'],'age_at_snapshot':p.get('age_at_snapshot'),
   'sex_reported':p.get('sex_reported'),'current_pcp':team('Primary care'),'current_cardiologist':team('Cardiology'),
   'program_review_rationale':(c['program_review']or{}).get('rationale'),
   'program_review_status':(c['program_review']or{}).get('status'),**row,
   'captured_answer_status':a.get('status'),
   'answer_source_reading_status':(context.get('source_disposition')or{}).get('status','not_assessed'),
   'patient_source_check_status':(c.get('source_verification')or{}).get('status','not_assessed'),
   'source_interpretation_notice':c.get('empty_source_reason')or(source_reading_notice(context)if(context.get('source_disposition')or{}).get('status')=='unavailable'else None)})
 field_labels={'on_rasi_pillar':'Recent RAAS inhibitor / ARNI fill','on_beta_blocker_pillar':'Recent evidence-based beta-blocker fill',
  'on_mra_pillar':'Recent MRA fill','on_sglt2i_pillar':'Recent SGLT2 inhibitor fill',
  'has_structured_current_cardiology_assignment':'Structured current cardiology assignment documented',
  'has_structured_current_primary_care_assignment':'Structured current primary-care assignment documented'}
 for field,text in {'on_raas_inhibitor':'RAAS inhibitor / ARNI','on_beta_blocker':'Evidence-based beta-blocker',
  'on_arni':'ARNI','on_mra':'MRA','on_sglt2i':'SGLT2 inhibitor'}.items():
  field_labels[field]=text+' fill membership (see saved time basis)'
 return {'layout':layout,'summary_metrics':summary_metrics(a,rows),'source_reading_notice':source_reading_notice(context),'source_disposition':context.get('source_disposition'),'recommendation_field_pattern':RECOMMENDATION_FIELD_PATTERN,'context_id':context.get('id'),'question':context['question'],'source':context['source'],'answer':a,'rows':rows,'patient_reviews':cards,'worklist_rows':worklist,'labels':{**field_labels,**(labels or{})},'title':title,'retained_inspection':bool(context.get('retained_inspection')),'evidence':evidence}

def exports(context,*,title='Evidence into next steps',evidence=None,layout='explore'):
 import csv,io
 data=payload(context,title=title,evidence=evidence,layout=layout)
 keys=list(dict.fromkeys(k for row in data['worklist_rows'] for k in row))
 def cell(v):
  if v is None:return 'Unknown / not supplied'
  return v if isinstance(v,str) else json.dumps(v,ensure_ascii=False,indent=2)
 out=io.StringIO(newline='');writer=csv.writer(out,quoting=csv.QUOTE_ALL,lineterminator='\r\n')
 writer.writerow(keys)
 writer.writerows([cell(row.get(k)) for k in keys] for row in data['worklist_rows'])
 return {'json':json.dumps(data,ensure_ascii=False,indent=2).encode('utf-8'),'csv':out.getvalue().encode('utf-8')}

def brief_overview(data):
 """Present recorded findings before the worklist; never author new analysis."""
 def value(v):
  if isinstance(v,list):return '<ul>'+''.join('<li>'+value(x)+'</li>'for x in v)+'</ul>'if v else'<p>No recorded items</p>'
  if isinstance(v,dict):return '<dl class="native-fields">'+''.join('<dt>'+html.escape(str(k).replace('_',' '))+'</dt><dd>'+
   ('<a href="'+html.escape(x,quote=True)+'">'+html.escape(x)+'</a>'if k=='url'and isinstance(x,str)and x.startswith(('https://','http://'))else value(x))+'</dd>'for k,x in v.items())+'</dl>'
  return html.escape('Unknown / not supplied'if v is None else str(v))
 def section(part):
  a=part.get('answer',part);heading=part.get('title')or part.get('label')or'Saved analytical findings'
  out='<section class="review-block"><h3>'+html.escape(str(heading))+'</h3>'
  if isinstance(a.get('headline'),str):out+='<p>'+html.escape(a['headline'])+'</p>'
  elif a.get('headline'):out+='<details><summary>Recorded headline fields</summary>'+value(a['headline'])+'</details>'
  for metric in summary_metrics(a,[]):out+='<p class="recorded-value"><strong>'+value(metric['value'])+'</strong> '+html.escape(str(metric['label']))+'</p>'
  for key in ('facts','missing','limitations','verification','investigation_review'):
   if a.get(key):out+='<h4>'+{'facts':'Recorded findings','missing':'Unresolved requirements','limitations':'Interpretation and financial assumptions','verification':'Saved verification status','investigation_review':'Recorded review findings — not a new assessment'}[key]+'</h4>'+value(a[key])
  rows=a.get('table')or[]
  if rows and not any('patient_id'in r for r in rows):
   out+='<div class="facts">'+''.join('<details class="fact"><summary>'+html.escape(str(r.get('source_domain')or r.get('name')or r.get('requirement_id')or'Recorded result'))+'</summary>'+value(r)+'</details>'for r in rows)+'</div>'
  elif rows:out+='<p>'+str(len(rows))+' recorded patient rows retained in the searchable records below.</p>'
  return out+'</section>'
 a=data['answer']
 return ('<section class="panel full-width" id="review-brief"><h2>Review agenda</h2>'
  '<p>Saved analytical status: <strong>'+html.escape(str(a.get('status')or'Not recorded'))+'</strong>. '
  +('All returned records remain available below. 'if data.get('rows')else'This answer has no individual result rows; use the saved aggregate or findings below. ')
  +'Clinical context uses the dated saved snapshot; later observations do not establish an earlier clinical state.</p>'
  +section(a)+''.join(section(s)for s in a.get('sections')or[]if isinstance(s,dict)and isinstance(s.get('answer'),dict))+'</section>')


def render(context,*,title='Evidence into next steps',pdf_url=None,labels=None,evidence=None,layout='explore'):
 data=payload(context,title=title,labels=labels,evidence=evidence,layout=layout)
 encoded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 # Encoding changes transport only. Keep every source, row and export field.
 # Small reports stay directly inspectable; large native evidence often repeats
 # across the answer, worklist and patient views and compresses substantially.
 if len(encoded.encode('utf-8'))>1024*1024:
  compressed=gzip.compress(encoded.encode('utf-8'),compresslevel=6,mtime=0)
  packed=json.dumps({'encoding':'gzip+base64','data':base64.b64encode(compressed).decode('ascii')})
  if len(packed)<len(encoded):encoded=packed
 link='<a class="button primary" href="'+html.escape(pdf_url,quote=True)+'" download>Download complete PDF</a>'if pdf_url else''
 replacements={'TITLE':html.escape(title),'PDF':link,'DATA':encoded,'PATIENTCSS':PATIENT_WORKSPACE_CSS+REPORT_PATIENT_CHROME,'PATIENTJS':PATIENT_WORKSPACE_JS,'BRIEF':brief_overview(data)if layout=='brief'else''}
 from ..application_shell import wrap
 return wrap(re.sub(r'%%([A-Z]+)%%',lambda m:replacements[m.group(1)],TEMPLATE),active='deliverables',title='Saved deliverable',context=context.get('id'))

